window.kbPageData["views/entry/k-7a709d4cd226d71e"] = {"key":"entry/k-7a709d4cd226d71e","state":{"route":"entry/k-7a709d4cd226d71e"},"node":{"id":"k-7a709d4cd226d71e","mode":"k","title":"新时代全面从严治党宝贵经验","type":"观点与论证","domain":"政治理论","reading":"","intro":"","priority":100,"aliases":[],"qs":[],"current":false,"candidates":false,"basisGroup":"","authority":null,"sourceOnly":true,"tags":{"专题":["party"],"主类":["观点与论证"],"出处性质":["机构注释"],"学科":["政治理论"],"来源主题":["党政制度与理论"],"资料类别":["非时政"]},"directorySummary":"3.新时代全面从严治党宝贵经验\n在新时代全面从严治党的伟大实践中，我们党积累了丰富的管党治党、兴党强党经\n验：\n1 从制定和落实中央八项规定开局破题，从抓作风入手推进全面从严治党；\n2 明确新时代党的建设总要求，把党的政治建设摆在党的建设统领位置；\n3 强调全面从严治党，核心是加强党的领导；\n4 坚…","sources":[{"id":"8258c0a163851d24","label":"新时代全面从严治党宝贵经验","topic":"党政制度与理论","category":"非时政","text":"3.新时代全面从严治党宝贵经验\n在新时代全面从严治党的伟大实践中，我们党积累了丰富的管党治党、兴党强党经\n验：\n1 从制定和落实中央八项规定开局破题，从抓作风入手推进全面从严治党；\n2 明确新时代党的建设总要求，把党的政治建设摆在党的建设统领位置；\n3 强调全面从严治党，核心是加强党的领导；\n4 坚持思想建党和制度治党有机结合、同向发力；\n5 反复强调打铁必须自身硬，把严的标准、严的措施贯穿于党的建设全过程和各\n方面，持续抓思想从严、监督从严、执纪从严、治吏从严、作风从严、反腐从严；\n6 注重整体谋划、系统推进，坚持党性党风党纪一起抓、正风肃纪反腐相贯通；\n7 坚持以上率下，从领导机关和领导干部严起、抓起，通过抓“关键少数”示范\n带动“绝大多数”；\n8 把党的建设融入党和国家事业发展大局，为推进中国式现代化提供坚强保障；\n——求是网","source":{"doc":"41195a191a57c1c36332","first":9,"last":9,"page":9,"file":"《中国共产党第二十届中央委员会第五次全体会议公报》解读.pdf"},"basis":"机构注释"}]},"questions":{},"terms":{},"references":{},"topics":[{"slug":"party","title":"党的建设与自我革命"}],"units":{"k-7a709d4cd226d71e":[]}};
